// Parse an Orderful 850 message into a clean canonical Order.
const first = (a) => (Array.isArray(a) && a.length ? a[0] : undefined);
function isoDate(edi) { if (!edi || edi.length !== 8) return edi ?? null; return `${edi.slice(0,4)}-${edi.slice(4,6)}-${edi.slice(6,8)}`; }
function productIds(item) { const ids = {}; for (const k of Object.keys(item)) { const m = k.match(/^productServiceIDQualifier(\d*)$/); if (!m) continue; const q = item[k]; const v = item[`productServiceID${m[1]}`]; if (q && v) ids[q] = v; } return ids; }
function party(loop, code) { const e = (loop ?? []).find((n) => first(n.partyIdentification)?.entityIdentifierCode === code); if (!e) return null; const id = first(e.partyIdentification); const loc = first(e.partyLocation); const geo = first(e.geographicLocation); return { name: id?.name ?? null, code: id?.identificationCode ?? null, address: loc?.addressInformation ?? null, city: geo?.cityName ?? null, state: geo?.stateOrProvinceCode ?? null, zip: geo?.postalCode ?? null, country: geo?.countryCode ?? null }; }
const DATE_Q = { '037': 'shipBy', '038': 'deliverBy', '002': 'requestedDelivery' };
const message = $json;
const set = first(message?.transactionSets);
if (!set) throw new Error('No transaction set found in 850 message');
const beg = first(set.beginningSegmentForPurchaseOrder) ?? {};
const terms = first(set.termsOfSaleDeferredTermsOfSale);
const dates = {};
for (const dtm of set.dateTimeReference ?? []) { const f = DATE_Q[dtm.dateTimeQualifier]; if (f) dates[f] = isoDate(dtm.date); }
const lines = (set.PO1_loop ?? []).map((po1) => { const base = first(po1.baselineItemData) ?? {}; const ids = productIds(base); return { line: base.assignedIdentification ?? null, sku: ids.SK ?? null, upc: ids.UP ?? null, qty: base.quantity != null ? Number(base.quantity) : null, uom: base.unitOrBasisForMeasurementCode ?? null, unitPrice: base.unitPrice != null ? Number(base.unitPrice) : null }; });
return { json: { poNumber: beg.purchaseOrderNumber ?? null, orderDate: isoDate(beg.date), terms: terms?.description ?? null, ...dates, shipTo: party(set.N1_loop, 'ST'), lines } };

// Build the AM order payload + Supabase log fields.
// AM's orders POST reads auth from the body, so time+token go in the payload.
const TOKEN = '197ec639dc944bc10509176dde7a8d72';
const order = $json;
const custResp = $('Get AM Customer').first().json;
const skuResp = $('Get AM SKU').first().json;
const customerId = custResp?.response?.[0]?.customer_id;
const skuId = skuResp?.response?.[0]?.sku_id;
if (!customerId) throw new Error('No customer_id from AM (check Get AM Customer output).');
if (!skuId) throw new Error('No sku_id from AM (check Get AM SKU output).');

const tx = $('Split Into Transactions').item.json;
const sender = tx.sender || {};

const items = (order.lines || []).map((l) => {
  const item = { sku_id: String(skuId), qty: String(l.qty), is_taxable: '1' };
  if (l.unitPrice != null) item.unit_price = String(l.unitPrice);
  return item;
});
const amPayload = {
  time: String(Math.floor(Date.now() / 1000)),
  token: TOKEN,
  '0': { header: { customer_id: String(customerId), customer_po: order.poNumber }, items },
};

const key = '850|' + (sender.isaId || 'UNKNOWN') + '|' + order.poNumber;
return { json: {
  poNumber: order.poNumber, dedupeKey: key, correlationId: key,
  partner: sender.name || null, stream: tx.stream || 'TEST',
  docType: '850', direction: 'inbound', status: 'processed', payloadRef: order.poNumber,
  externalIds: JSON.stringify({ orderfulId: tx.id, poNumber: order.poNumber, businessNumber: tx.businessNumber, customerId, skuId }),
  amPayload,
} };
